<?php
declare(strict_types=1);
date_default_timezone_set('Asia/Karachi');
require_once __DIR__ . '/../app/bootstrap.php';
$user = require_role('admin');
$pdo = db();
function sd_inv_h(string $v): string { return htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function sd_inv_num(mixed $v): ?float { if (!is_string($v) && !is_numeric($v)) return null; if (!is_numeric($v)) return null; $n=(float)$v; return is_finite($n) ? $n : null; }
function sd_inv_redirect(): never { header('Location: inventory.php'); exit; }
$error = ''; $flash = (string)($_SESSION['sd_inventory_flash'] ?? ''); unset($_SESSION['sd_inventory_flash']);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf($_POST['_csrf'] ?? null)) { $error='Your security token expired. Refresh the page and try again.'; }
    else {
        $action=(string)($_POST['action'] ?? '');
        try {
            if ($action === 'create_item') {
                $name=trim((string)($_POST['name'] ?? '')); $sku=trim((string)($_POST['sku'] ?? '')); $category=trim((string)($_POST['category'] ?? '')); $unit=trim((string)($_POST['unit'] ?? 'unit'));
                $qty=sd_inv_num($_POST['initial_quantity'] ?? null); $reorder=sd_inv_num($_POST['reorder_level'] ?? null); $cost=sd_inv_num($_POST['unit_cost'] ?? null);
                if ($name==='' || strlen($name)>160) throw new InvalidArgumentException('Enter an item name of up to 160 characters.');
                if (strlen($sku)>60 || strlen($category)>120 || $unit==='' || strlen($unit)>30) throw new InvalidArgumentException('Check the SKU, category, or unit length.');
                if ($qty===null || $qty<0 || $reorder===null || $reorder<0 || $cost===null || $cost<0) throw new InvalidArgumentException('Quantity, reorder level, and cost must be zero or positive numbers.');
                $pdo->beginTransaction();
                $q=$pdo->prepare('INSERT INTO inventory_items (sku,name,category,unit,quantity_on_hand,reorder_level,unit_cost,created_by) VALUES (?,?,?,?,?,?,?,?)');
                $q->execute([$sku===''?null:$sku,$name,$category===''?null:$category,$unit,$qty,$reorder,$cost,(int)$user['id']]); $id=(int)$pdo->lastInsertId();
                if ($qty>0) { $m=$pdo->prepare("INSERT INTO inventory_movements (item_id,movement_type,quantity_delta,quantity_before,quantity_after,unit_cost_snapshot,notes,created_by) VALUES (?,'restock',?,0,?,?,?,?)"); $m->execute([$id,$qty,$qty,$cost,'Opening stock',(int)$user['id']]); }
                $pdo->commit(); $_SESSION['sd_inventory_flash']='Inventory item created.'; sd_inv_redirect();
            } elseif ($action === 'movement') {
                $itemId=filter_var($_POST['item_id'] ?? null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]); $type=(string)($_POST['movement_type'] ?? ''); $amount=sd_inv_num($_POST['amount'] ?? null); $notes=trim((string)($_POST['notes'] ?? ''));
                if (!$itemId || !in_array($type,['restock','use','damage','adjustment'],true)) throw new InvalidArgumentException('Choose an item and valid movement type.');
                if ($amount===null || $amount==0 || abs($amount)>1000000000) throw new InvalidArgumentException('Enter a non-zero quantity within the supported range.');
                if ($type!=='adjustment' && $amount<0) throw new InvalidArgumentException('For restock, use, or damage, enter a positive quantity.');
                if (strlen($notes)>500) throw new InvalidArgumentException('Notes must be no longer than 500 characters.');
                $delta=$type==='restock' ? abs($amount) : (in_array($type,['use','damage'],true) ? -abs($amount) : $amount);
                $pdo->beginTransaction(); $q=$pdo->prepare('SELECT * FROM inventory_items WHERE id=? AND is_active=1 FOR UPDATE'); $q->execute([(int)$itemId]); $item=$q->fetch();
                if (!$item) throw new InvalidArgumentException('Active inventory item not found.');
                $before=(float)$item['quantity_on_hand']; $after=$before+$delta;
                if ($after < -0.0001) throw new InvalidArgumentException('This movement would make stock negative. Check the quantity and try again.');
                if (abs($after)<0.0005) $after=0.0;
                $u=$pdo->prepare('UPDATE inventory_items SET quantity_on_hand=? WHERE id=?'); $u->execute([$after,(int)$itemId]);
                $m=$pdo->prepare('INSERT INTO inventory_movements (item_id,movement_type,quantity_delta,quantity_before,quantity_after,unit_cost_snapshot,notes,created_by) VALUES (?,?,?,?,?,?,?,?)');
                $m->execute([(int)$itemId,$type,$delta,$before,$after,(float)$item['unit_cost'],$notes===''?null:$notes,(int)$user['id']]);
                $pdo->commit(); $_SESSION['sd_inventory_flash']='Stock movement saved.'; sd_inv_redirect();
            } else throw new InvalidArgumentException('Unknown inventory action.');
        } catch (InvalidArgumentException $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $error=$e->getMessage(); }
        catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); error_log('SalonDiva inventory error: '.$e->getMessage()); $error='Could not save the inventory change. Check that the Calendar & Analytics database migration has been installed and that the SKU is not duplicated.'; }
    }
}
try {
    $items=$pdo->query('SELECT * FROM inventory_items ORDER BY is_active DESC,name')->fetchAll();
    $activeItems=$pdo->query('SELECT id,name,sku,unit,quantity_on_hand FROM inventory_items WHERE is_active=1 ORDER BY name')->fetchAll();
    $movements=$pdo->query('SELECT m.*,i.name item_name,i.unit,u.name actor_name FROM inventory_movements m JOIN inventory_items i ON i.id=m.item_id LEFT JOIN users u ON u.id=m.created_by ORDER BY m.created_at DESC,m.id DESC LIMIT 50')->fetchAll();
} catch (Throwable $e) { http_response_code(500); echo '<!doctype html><meta charset="utf-8"><h1>Inventory setup is incomplete</h1><p>Run database/calendar_analytics_migration.sql in the salondiva database, then refresh this page.</p>'; exit; }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory · SalonDiva</title><style>
:root{--ink:#321d2a;--pink:#c52f63;--bg:#fff6f9;--line:#ead8e1;--muted:#806c77;--cream:#fffdf9;--green:#e3f5e8;--red:#fbe4e8;--gold:#fff1ce}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}.wrap{max-width:1200px;margin:24px auto;padding:0 14px}.shell{background:var(--cream);border:1px solid var(--line);border-radius:20px;padding:clamp(14px,2.5vw,26px)}.brand{font-weight:850;color:var(--pink)}h1{margin:.25rem 0}h2{font-size:1.15rem;margin-top:0}.muted,.hint{color:var(--muted)}.nav{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.btn{display:inline-block;background:var(--pink);color:#fff;padding:9px 12px;border-radius:9px;text-decoration:none;font-weight:700;border:0;cursor:pointer}.btn.light{background:#f5e5ec;color:var(--ink)}.section{margin-top:16px;background:white;border:1px solid var(--line);border-radius:14px;padding:16px}.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:14px}.formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.field{display:flex;flex-direction:column;gap:5px}.field input,.field select,.field textarea{width:100%;padding:9px;border:1px solid #dfcbd4;border-radius:8px;font:inherit}.field textarea{min-height:70px}.alert{padding:11px;border-radius:9px;margin:12px 0;background:var(--green)}.alert.error{background:var(--red)}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:680px}th,td{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid var(--line)}th{background:#fbf0f4}.pill{padding:3px 7px;border-radius:99px;background:#f5e5ec}.pill.low{background:var(--gold);color:#715200}.pill.off{background:var(--red)}@media(max-width:600px){.section{padding:11px}}
</style></head><body><main class="wrap"><div class="shell"><div class="brand">SalonDiva</div><h1>Inventory management</h1><p class="muted">Track supplies, quantities, reorder levels, restocks, usage, and damage. All stock changes are recorded in a movement log.</p><div class="nav"><a class="btn light" href="dashboard.php">Dashboard</a><a class="btn light" href="calendar.php">Calendar</a><a class="btn light" href="reports.php">Reports & analytics</a></div>
<?php if($flash!==''): ?><div class="alert"><?=sd_inv_h($flash)?></div><?php endif; ?><?php if($error!==''): ?><div class="alert error"><?=sd_inv_h($error)?></div><?php endif; ?>
<div class="two"><section class="section"><h2>Add inventory item</h2><form method="post"><input type="hidden" name="_csrf" value="<?=sd_inv_h(csrf_token())?>"><input type="hidden" name="action" value="create_item"><div class="formgrid"><div class="field"><label>Item name *</label><input name="name" maxlength="160" required></div><div class="field"><label>SKU (optional)</label><input name="sku" maxlength="60"></div><div class="field"><label>Category</label><input name="category" maxlength="120" placeholder="e.g. Hair care"></div><div class="field"><label>Unit</label><input name="unit" maxlength="30" value="unit" required></div><div class="field"><label>Opening quantity *</label><input name="initial_quantity" type="number" min="0" step="0.001" value="0" required></div><div class="field"><label>Low-stock alert at *</label><input name="reorder_level" type="number" min="0" step="0.001" value="0" required></div><div class="field"><label>Unit cost (PKR) *</label><input name="unit_cost" type="number" min="0" step="0.01" value="0" required></div></div><p class="hint">Opening quantity is recorded as an initial restock movement.</p><button class="btn" type="submit">Add item</button></form></section>
<section class="section"><h2>Record stock movement</h2><form method="post"><input type="hidden" name="_csrf" value="<?=sd_inv_h(csrf_token())?>"><input type="hidden" name="action" value="movement"><div class="field"><label>Inventory item *</label><select name="item_id" required><option value="">Choose an item</option><?php foreach($activeItems as $i): ?><option value="<?=(int)$i['id']?>"><?=sd_inv_h((string)$i['name'])?> · <?=number_format((float)$i['quantity_on_hand'],3)?> <?=sd_inv_h((string)$i['unit'])?></option><?php endforeach; ?></select></div><div class="formgrid"><div class="field"><label>Movement *</label><select name="movement_type" id="movement_type" required><option value="restock">Restock (adds stock)</option><option value="use">Used (removes stock)</option><option value="damage">Damaged (removes stock)</option><option value="adjustment">Adjustment (+/-)</option></select></div><div class="field"><label>Quantity *</label><input name="amount" type="number" step="0.001" required></div></div><div class="field"><label>Notes</label><textarea name="notes" maxlength="500" placeholder="Optional reason or usage details"></textarea></div><p class="hint">For restock/use/damage, enter a positive quantity. For Adjustment, enter a positive or negative change. Stock cannot go below zero.</p><button class="btn" type="submit">Save movement</button></form></section></div>
<section class="section"><h2>Stock on hand</h2><div class="tablewrap"><table><thead><tr><th>Item</th><th>SKU</th><th>Category</th><th>On hand</th><th>Reorder level</th><th>Unit cost</th><th>Status</th></tr></thead><tbody><?php foreach($items as $i): $low=(float)$i['quantity_on_hand']<=(float)$i['reorder_level']; ?><tr><td><?=sd_inv_h((string)$i['name'])?></td><td><?=sd_inv_h((string)($i['sku']??''))?></td><td><?=sd_inv_h((string)($i['category']??''))?></td><td><?=number_format((float)$i['quantity_on_hand'],3)?> <?=sd_inv_h((string)$i['unit'])?></td><td><?=number_format((float)$i['reorder_level'],3)?></td><td>PKR <?=number_format((float)$i['unit_cost'],2)?></td><td><span class="pill <?=$low?'low':''?> <?=$i['is_active']?'':'off'?>"><?=$i['is_active']?($low?'Low stock':'In stock'):'Inactive'?></span></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="7">No inventory items yet. Add your first item above.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="section"><h2>Recent stock movements</h2><div class="tablewrap"><table><thead><tr><th>Date</th><th>Item</th><th>Movement</th><th>Change</th><th>Balance</th><th>Notes</th><th>Recorded by</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?=sd_inv_h(date('d M Y H:i',strtotime((string)$m['created_at'])))?></td><td><?=sd_inv_h((string)$m['item_name'])?></td><td><?=sd_inv_h(ucfirst((string)$m['movement_type']))?></td><td><?=((float)$m['quantity_delta']>0?'+':'').number_format((float)$m['quantity_delta'],3)?> <?=sd_inv_h((string)$m['unit'])?></td><td><?=number_format((float)$m['quantity_after'],3)?> <?=sd_inv_h((string)$m['unit'])?></td><td><?=sd_inv_h((string)($m['notes']??''))?></td><td><?=sd_inv_h((string)($m['actor_name']??''))?></td></tr><?php endforeach; ?><?php if(!$movements): ?><tr><td colspan="7">No stock movements yet.</td></tr><?php endif; ?></tbody></table></div></section>
</div></main></body></html>
